// Loop over input items and add a new field called 'myNewField' to the JSON of each one


function getPV(propertyID, value){

    let pv = {
       "@type": "PropertyValue",
      "propertyID": propertyID,
      "value": value
    }
  return pv
}



for (const item of $input.all()) {
  let r = item.json.body.data?.[0] || item.json.body.data


  let newAction = {
    "@type": "Action",
    "@id": item.json.body.metadata['@id'] + "/hasPart/" + item.json.body.id,
    "timeStart": new Date().toISOString(),
    "timeEnd": new Date().toISOString(),
    "name": "Scrape webpage",
    "actionStatus": "CompletedActionStatus"

  }


  let record = {
    "@type": "WebPage",
    "@id": (r.metadata.sourceURL || "") + "#webpage",
    "url": r.metadata?.sourceURL,
    "additionalProperty": []
  }

  for(let k of Object.keys(r)){
    record.additionalProperty.push(getPV(k, r?.[k]))
  }

  newAction.result = record

  let parentAction = {
    "@type": "Action",
    "@id": item.json.body.metadata['@id'],
    "hasPart": newAction
  }



  item.json = {}
  item.json.action = parentAction



}

return $input.all();

